test('local column-percent-type assignment matches actual payment INSERT outcomes',async()=>{
 const c=new Client({connectionString:process.env.DATABASE_URL});await c.connect();
 try {await c.query('BEGIN');await c.query(`CREATE FUNCTION pg_temp.b019_assign_probe(raw text) RETURNS text LANGUAGE plpgsql AS $$ DECLARE v public.payments.payer_account_last5%TYPE; BEGIN v:=NULLIF(raw,'');IF v IS NOT NULL AND v !~ '^[0-9]{5}$' THEN RAISE EXCEPTION 'check' USING ERRCODE='23514';END IF;RETURN v::text; END $$`);
  for(const [raw,expectedCode] of [['12345',null],['12345 ',null],['123456','22001'],['123456 ','22001'],['12345\t','22001'],['12345\u00a0','22001'],['1234','23514'],['',null],['     ','23514']] as [string,string|null][]){
   let expected:string|null=null,actual:string|null=null,expectedError:string|null=null,actualError:string|null=null;
   await c.query('SAVEPOINT assign_case');try{expected=(await c.query<{v:string|null}>(`SELECT pg_temp.b019_assign_probe($1) v`,[raw])).rows[0].v;}catch(e){expectedError=(e as {code:string}).code;}await c.query('ROLLBACK TO SAVEPOINT assign_case');
   await c.query('SAVEPOINT insert_case');try{const inserted=await c.query<{v:string|null}>(`INSERT INTO payments(org_id,property_id,lease_id,currency,amount_minor,paid_on,method,payer_account_last5,status,source,submitted_by) SELECT org_id,property_id,id,currency,1,current_date,'bank_transfer',NULLIF($2::text,''),'submitted','manager_entry',$3 FROM leases WHERE org_id=$1 LIMIT 1 RETURNING payer_account_last5::text v`,[ORG_ID,raw,USERS.admin]);assert.equal(inserted.rowCount,1);actual=inserted.rows[0].v;}catch(e){actualError=(e as {code:string}).code;}await c.query('ROLLBACK TO SAVEPOINT insert_case');
   assert.equal(expectedError,expectedCode,`assignment SQLSTATE differs for input length ${raw.length}`);assert.equal(actualError,expectedCode,`insert SQLSTATE differs for input length ${raw.length}`);if(expectedCode===null){assert.equal(expected,actual);if(raw==='')assert.equal(actual,null);}
  }await c.query('ROLLBACK');
 } finally {await c.end();}
});

