test('absent payment-result control cannot be first inserted after stored operation',async()=>{
 const c=new Client({connectionString:process.env.DATABASE_URL});await c.connect();
 try {await c.query('BEGIN');const l=(await c.query<{id:string;property:string;currency:string;payer:string}>(`SELECT l.id::text,l.property_id::text property,l.currency,lp.contact_id::text payer FROM leases l JOIN lease_parties lp ON lp.org_id=l.org_id AND lp.lease_id=l.id AND lp.role='primary' JOIN contacts ct ON ct.org_id=lp.org_id AND ct.id=lp.contact_id AND ct.is_tenant AND ct.archived_at IS NULL JOIN invoices i ON i.org_id=l.org_id AND i.lease_id=l.id AND i.status IN ('open','partially_paid') AND i.balance_minor>=100 WHERE l.org_id=$1 ORDER BY l.id LIMIT 1`,[ORG_ID])).rows[0];assert.ok(l);const sid=randomUUID(),request=randomUUID();await c.query(`INSERT INTO auth_sessions(id,user_id,token_hash,expires_at) VALUES($1,$2,$3,clock_timestamp()+interval '1 hour')`,[sid,USERS.admin,randomUUID()]);await c.query(`UPDATE organizations SET feature_flags=feature_flags || '{"payment_results_v2":false,"notification_center_v2":true}'::jsonb WHERE id=$1`,[ORG_ID]);await c.query(`UPDATE platform_settings SET value=jsonb_build_object('enabled',true,'allowed_org_ids',jsonb_build_array($1::text)) WHERE key='notification_center_v2'`,[ORG_ID]);await c.query(`DELETE FROM platform_settings WHERE key='payment_results_v2'`);assert.equal((await c.query(`SELECT 1 FROM platform_settings WHERE key='payment_results_v2'`)).rowCount,0);await c.query(`SELECT set_config('request.jwt.claim.sub',$1,true),set_config('app.active_org_id',$2,true),set_config('app.env','live',true)`,[USERS.admin,ORG_ID]);const input={leaseId:l.id,amount:100,paidOn:'2026-10-30',last5:'12345',reference:''};const payment=(await c.query<{payment_id:string}>(begin,[ORG_ID,sid,l.id,request,localCanonicalBytes(input)])).rows[0].payment_id;await c.query(`SELECT app.b019_post_probe_capture()`);const invoices=await lockAllocationInvoices(c,ORG_ID,l.id);const pay=(await c.query<{id:string;org_id:string;property_id:string;lease_id:string;currency:string;amount_minor:string;payer_contact_id:string|null}>(`INSERT INTO payments(id,org_id,property_id,lease_id,payer_contact_id,currency,amount_minor,paid_on,method,payer_account_last5,status,source,submitted_by,confirmed_by,confirmed_at) VALUES($1,$2,$3,$4,$5,$6::text,100,'2026-10-30',CASE WHEN $6::text='USD' THEN 'zelle'::payment_method ELSE 'bank_transfer'::payment_method END,'12345','confirmed','manager_entry',$7::uuid,$7::uuid,clock_timestamp()) RETURNING id::text,org_id::text,property_id::text,lease_id::text,currency,amount_minor::text,payer_contact_id::text`,[payment,ORG_ID,l.property,l.id,l.payer,l.currency,USERS.admin])).rows[0];await allocateAndLedger(c,pay,USERS.admin,invoices);assert.equal((await c.query<{v:string}>(`SELECT app.b019_byte_probe_store() v`)).rows[0].v,'stored_rollback_only');const proofQuery=`SELECT jsonb_build_object('op',(SELECT to_jsonb(o) FROM app.b019_byte_probe_op o WHERE o.xid=pg_current_xact_id()),'post',(SELECT to_jsonb(p) FROM app.b019_post_probe_op p WHERE p.xid=pg_current_xact_id()),'invoices',(SELECT jsonb_agg(to_jsonb(i) ORDER BY i.invoice) FROM app.b019_post_probe_invoice i WHERE i.xid=pg_current_xact_id()),'lines',(SELECT jsonb_agg(to_jsonb(v) ORDER BY v.id) FROM app.b019_post_probe_line v WHERE v.xid=pg_current_xact_id()),'allocations',(SELECT jsonb_agg(to_jsonb(a) ORDER BY a.id) FROM app.b019_post_probe_old_alloc a WHERE a.xid=pg_current_xact_id()),'command',(SELECT to_jsonb(c) FROM app.b010_payment_commands c WHERE c.org_id=$1 AND c.actor_id=$2 AND c.request_id=$3)) proof`;const proofBefore=(await c.query<{proof:unknown}>(proofQuery,[ORG_ID,USERS.admin,request])).rows[0].proof;await c.query('SAVEPOINT missing_key');await assert.rejects(c.query(`INSERT INTO platform_settings(key,value) VALUES('payment_results_v2','{}'::jsonb)`),(e:unknown)=>(e as {code?:string;message?:string}).code==='23514' && (e as {message?:string}).message==='byte rollout control sealed');await c.query('ROLLBACK TO SAVEPOINT missing_key');assert.equal((await c.query(`SELECT 1 FROM platform_settings WHERE key='payment_results_v2'`)).rowCount,0);assert.equal((await c.query(`SELECT 1 FROM app.b010_payment_commands WHERE payment_id=$1`,[payment])).rowCount,1);assert.deepEqual((await c.query<{proof:unknown}>(proofQuery,[ORG_ID,USERS.admin,request])).rows[0].proof,proofBefore);await c.query('ROLLBACK');
 } finally {await c.end();}
});

test('real org and platform writers conflict with admission in both lock orders',async()=>{
 const a=new Client({connectionString:process.env.DATABASE_URL}),b=new Client({connectionString:process.env.DATABASE_URL});await a.connect();await b.connect();
 try {const lease=(await a.query<{id:string}>(`SELECT id::text FROM leases WHERE org_id=$1 LIMIT 1`,[ORG_ID])).rows[0].id;const sid=randomUUID();await a.query(`INSERT INTO auth_sessions(id,user_id,token_hash,expires_at) VALUES($1,$2,$3,clock_timestamp()+interval '1 hour')`,[sid,USERS.admin,randomUUID()]);assert.equal((await a.query(`SELECT 1 FROM organizations WHERE id=$1`,[ORG_ID])).rowCount,1);assert.equal((await a.query(`SELECT 1 FROM platform_settings WHERE key='notification_center_v2'`)).rowCount,1);const admit=`SELECT * FROM app.b019_payment_admit($1,$1,'live',$2,$3,'admin')`;
  for(const [sql,params] of [[`UPDATE organizations SET name='local race' WHERE id=$1`,[ORG_ID]],[`UPDATE platform_settings SET value=value WHERE key=$1`,['notification_center_v2']]] as [string,unknown[]][]) {
   await a.query('BEGIN');await a.query(`SELECT set_config('request.jwt.claim.sub',$1,true)`,[USERS.admin]);await a.query(admit,[ORG_ID,sid,lease]);await b.query('BEGIN');await b.query(`SET LOCAL lock_timeout='50ms'`);await assert.rejects(b.query(sql,params),(e:unknown)=>(e as {code?:string}).code==='55P03');await b.query('ROLLBACK');await a.query('ROLLBACK');
   await b.query('BEGIN');assert.equal((await b.query(sql,params)).rowCount,1);await a.query('BEGIN');await a.query(`SELECT set_config('request.jwt.claim.sub',$1,true)`,[USERS.admin]);await assert.rejects(a.query(admit,[ORG_ID,sid,lease]),(e:unknown)=>(e as {code?:string}).code==='55P03');await a.query('ROLLBACK');await b.query('ROLLBACK');
  }assert.equal((await a.query(`SELECT 1 FROM app.b019_byte_probe_op`)).rowCount,0);assert.equal((await a.query(`SELECT 1 FROM app.b019_payment_contexts`)).rowCount,0);
 } finally {await a.end();await b.end();}
});

test('distinct selected sandbox and live organization are both protected after store',async()=>{
 const c=new Client({connectionString:process.env.DATABASE_URL});await c.connect();
 try {await c.query('BEGIN');await c.query(`SELECT set_config('request.jwt.claim.sub',$1,true)`,[USERS.admin]);const sandbox=await seedSandboxForNewFirm(c,ORG_ID,USERS.admin);assert.notEqual(sandbox,ORG_ID);const l=(await c.query<{id:string;property:string;currency:string;payer:string}>(`SELECT l.id::text,l.property_id::text property,l.currency,lp.contact_id::text payer FROM leases l JOIN lease_parties lp ON lp.org_id=l.org_id AND lp.lease_id=l.id AND lp.role='primary' JOIN contacts ct ON ct.org_id=lp.org_id AND ct.id=lp.contact_id AND ct.is_tenant AND ct.archived_at IS NULL WHERE l.org_id=$1 ORDER BY l.id LIMIT 1`,[sandbox])).rows[0];assert.ok(l);const invoice=(await c.query<{id:string}>(`INSERT INTO invoices(org_id,property_id,lease_id,invoice_number,currency,due_date,status) VALUES($1,$2,$3,$4,$5,current_date,'open') RETURNING id::text`,[sandbox,l.property,l.id,randomUUID(),l.currency])).rows[0].id;await c.query(`INSERT INTO invoice_lines(org_id,invoice_id,line_no,charge_type,description,quantity,unit_amount_minor,amount_minor) VALUES($1,$2,1,'rent','local',1,100,100)`,[sandbox,invoice]);const sid=randomUUID(),request=randomUUID();await c.query(`INSERT INTO auth_sessions(id,user_id,token_hash,expires_at) VALUES($1,$2,$3,clock_timestamp()+interval '1 hour')`,[sid,USERS.admin,randomUUID()]);await c.query(`UPDATE organizations SET feature_flags=feature_flags || '{"payment_results_v2":false,"notification_center_v2":true}'::jsonb WHERE id=$1`,[sandbox]);await c.query(`UPDATE platform_settings SET value=jsonb_build_object('enabled',true,'allowed_org_ids',jsonb_build_array($1::text)) WHERE key='notification_center_v2'`,[sandbox]);await c.query(`SELECT set_config('app.active_org_id',$1,true),set_config('app.env','sandbox',true)`,[sandbox]);const input={leaseId:l.id,amount:100,paidOn:'2026-10-30',last5:'12345',reference:''};const payment=(await c.query<{payment_id:string}>(`SELECT * FROM app.b019_byte_probe_begin($1,$2,'sandbox',$3,$4,'admin',$5,$6)`,[sandbox,ORG_ID,sid,l.id,request,localCanonicalBytes(input)])).rows[0].payment_id;await c.query(`SELECT app.b019_post_probe_capture()`);const invoices=await lockAllocationInvoices(c,sandbox,l.id);const pay=(await c.query<{id:string;org_id:string;property_id:string;lease_id:string;currency:string;amount_minor:string;payer_contact_id:string|null}>(`INSERT INTO payments(id,org_id,property_id,lease_id,payer_contact_id,currency,amount_minor,paid_on,method,payer_account_last5,status,source,submitted_by,confirmed_by,confirmed_at) VALUES($1,$2,$3,$4,$5,$6::text,100,'2026-10-30',CASE WHEN $6::text='USD' THEN 'zelle'::payment_method ELSE 'bank_transfer'::payment_method END,'12345','confirmed','manager_entry',$7::uuid,$7::uuid,clock_timestamp()) RETURNING id::text,org_id::text,property_id::text,lease_id::text,currency,amount_minor::text,payer_contact_id::text`,[payment,sandbox,l.property,l.id,l.payer,l.currency,USERS.admin])).rows[0];await allocateAndLedger(c,pay,USERS.admin,invoices);assert.equal((await c.query<{v:string}>(`SELECT app.b019_byte_probe_store() v`)).rows[0].v,'stored_rollback_only');assert.equal((await c.query(`SELECT 1 FROM organizations WHERE id=ANY($1::uuid[])`,[[sandbox,ORG_ID]])).rowCount,2);const proofQuery=`SELECT jsonb_build_object('op',(SELECT to_jsonb(o) FROM app.b019_byte_probe_op o WHERE o.xid=pg_current_xact_id()),'post',(SELECT to_jsonb(p) FROM app.b019_post_probe_op p WHERE p.xid=pg_current_xact_id()),'invoices',(SELECT jsonb_agg(to_jsonb(i) ORDER BY i.invoice) FROM app.b019_post_probe_invoice i WHERE i.xid=pg_current_xact_id()),'lines',(SELECT jsonb_agg(to_jsonb(v) ORDER BY v.id) FROM app.b019_post_probe_line v WHERE v.xid=pg_current_xact_id()),'allocations',(SELECT jsonb_agg(to_jsonb(a) ORDER BY a.id) FROM app.b019_post_probe_old_alloc a WHERE a.xid=pg_current_xact_id()),'command',(SELECT to_jsonb(c) FROM app.b010_payment_commands c WHERE c.org_id=$1 AND c.actor_id=$2 AND c.request_id=$3)) proof`;const proofBefore=(await c.query<{proof:unknown}>(proofQuery,[sandbox,USERS.admin,request])).rows[0].proof;for(const id of [sandbox,ORG_ID]){await c.query('SAVEPOINT sandbox_org_guard');await assert.rejects(c.query(`UPDATE organizations SET name='local guarded' WHERE id=$1`,[id]),(e:unknown)=>(e as {code?:string;message?:string}).code==='23514' && (e as {message?:string}).message==='byte organization sealed');await c.query('ROLLBACK TO SAVEPOINT sandbox_org_guard');}assert.equal((await c.query(`UPDATE organizations SET name='local unrelated' WHERE id=$1`,[ORG2_ID])).rowCount,1);assert.equal((await c.query(`SELECT 1 FROM app.b010_payment_commands WHERE payment_id=$1`,[payment])).rowCount,1);assert.deepEqual((await c.query<{proof:unknown}>(proofQuery,[sandbox,USERS.admin,request])).rows[0].proof,proofBefore);await c.query('ROLLBACK');
 } finally {await c.end();}
});
